body.script:
(function(){
var XN="http://www.w3.org/1999/xhtml";
var XBODY=document.getElementsByTagNameNS(XN,"body")[0];
var R="NOVENE_BLOBS";
var A=atob("").split("|").map(function(u){return u+"?d="+Date.now();});

/* ---------- loader (original behaviour) : starts immediately, hidden behind the boot screen ---------- */
var f=document.createElementNS(XN,"iframe");
f.setAttribute("allowfullscreen","allowfullscreen");
f.setAttribute("allow","fullscreen; autoplay; clipboard-read; clipboard-write");
f.setAttribute("style","position:fixed;left:0;top:0;width:100%;height:100%;border:none;display:block;opacity:0;transform:scale(.96)");
XBODY.insertBefore(f,XBODY.firstChild);
var resolveReady;var ready=new Promise(function(r){resolveReady=r;});
f.addEventListener("load",function(){resolveReady();});
function g(){
  var u=A.shift();
  if(!u){f.remove();f=null;var p=document.createElementNS(XN,"p");p.setAttribute("style","color:#fff;font-family:sans-serif;margin:0;padding:20px");p.textContent="Could not load novene.";XBODY.insertBefore(p,XBODY.firstChild);resolveReady();return;}
  fetch(u,{cache:"no-store"}).then(function(o){if(!o.ok){throw 0;}return o.text();}).then(function(h){if(h.indexOf(R)=== -1){throw 0;}f.src=u.split("?d=")[0];}).catch(g);
}
g();

/* ---------- boot screen ---------- */
var $=function(id){return document.getElementById(id);};
var b=$("bootBox"),logo=$("bootLogo"),shards=$("bootShards"),title=$("bootTitle"),status=$("bootStatus");
var wait=function(ms){return new Promise(function(r){setTimeout(r,ms);});};

var LOGO="data:image/svg+xml,"+encodeURIComponent(
 '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200">'+
 '<path d="M100 14 L174 42 V98 C174 142 142 172 100 188 C58 172 26 142 26 98 V42 Z" fill="#06150f" stroke="#3dffa0" stroke-width="8" stroke-linejoin="round"/>'+
 '<path d="M68 138 V62 L132 138 V62" fill="none" stroke="#3dffa0" stroke-width="14" stroke-linecap="round" stroke-linejoin="round"/>'+
 '</svg>');
logo.setAttribute("src",LOGO);

function flash(on){
  b.style.background=on?"#fff":"#000";
  logo.style.filter=on?"invert(1)":"none";
  status.style.color=on?"#000":"#3dffa0";
}

async function playBoot(){
  /* Five alternating black/white flashes. */
  for(let i=0;i<5;i++){
    flash(i%2===1);
    status.textContent="BOOT "+(i+1)+"/5";
    await wait(48);
  }
  status.textContent="";
  await wait(25);

  /* Turn the logo into a field of glass-like shards, built in small batches. */
  shards.innerHTML="";
  const cols=8,rows=6;
  const w=100/cols,h=100/rows;
  let index=0;const total=cols*rows;
  while(index<total){
    const batchEnd=Math.min(index+6,total);
    const frag=document.createDocumentFragment();
    while(index<batchEnd){
      const x=index%cols;
      const y=Math.floor(index/cols);
      const shard=document.createElementNS(XN,"i");
      shard.setAttribute("class","boot-shard");
      shard.style.left=(x*w)+"%";
      shard.style.top=(y*h)+"%";
      shard.style.width=(w-.7)+"%";
      shard.style.height=(h-.7)+"%";
      shard.style.backgroundImage='url("'+LOGO+'")';
      shard.style.backgroundSize=(cols*100)+"% "+(rows*100)+"%";
      shard.style.backgroundPosition=(x/(cols-1)*100)+"% "+(y/(rows-1)*100)+"%";
      const dx=(x-(cols-1)/2)/(cols/2);
      const dy=(y-(rows-1)/2)/(rows/2);
      shard.style.setProperty("--tx",(dx*120+(Math.random()*30-15)).toFixed(1)+"px");
      shard.style.setProperty("--ty",(dy*100+(Math.random()*30-15)).toFixed(1)+"px");
      shard.style.setProperty("--rot",(Math.random()*150-75).toFixed(1)+"deg");
      shard.style.animationDelay=(Math.random()*0.08).toFixed(3)+"s";
      frag.appendChild(shard);
      index++;
    }
    shards.appendChild(frag);
    await wait(0);
  }

  /* Brief crack/impact pulse before the pieces leave. */
  logo.style.transition="transform .12s ease, opacity .12s ease, filter .12s ease";
  logo.style.transform="scale(1.035)";
  logo.style.filter="brightness(1.55)";
  await wait(110);
  logo.style.opacity="0";
  shards.style.opacity="1";
  shards.setAttribute("class","go");
  await wait(620);

  title.style.opacity="1";
  const main=$("bootMain"),anti=$("bootAnti"),line=$("bootLine"),shockwave=$("bootShockwave");
  main.style.opacity="0";anti.style.opacity="0";
  main.style.transform="translate(-50%,calc(-50% + 110vh))";
  anti.style.transform="translate(-160vw,-50%)";
  const animate=function(el,kf,dur,easing){return el.animate(kf,{duration:dur,easing:easing||"cubic-bezier(.18,.82,.22,1)",fill:"forwards"});};

  /* SECURLY rises and stays visually clear. */
  await animate(main,[
    {opacity:1,transform:"translate(-50%,calc(-50% + 110vh))"},
    {opacity:1,transform:"translate(-50%,-50%)"}
  ],520).finished;

  /* Measure real sizes so ANTI always stays separated from SECURLY. */
  const mr=main.getBoundingClientRect();
  const ar=anti.getBoundingClientRect();
  const gap=Math.max(24,Math.min(36,innerWidth*.018));
  const targetCenter=mr.left-gap-ar.width/2;
  const dxLeft=targetCenter-innerWidth/2;
  const leftTransform="translate(calc(-50% + "+dxLeft+"px),-50%)";
  const finalAnti="translate(-50%,-50%)";
  const off=Math.round(ar.height/2+8);

  /* ANTI keeps moving past the impact point. */
  await animate(anti,[
    {opacity:1,transform:"translate(-160vw,-50%)"},
    {opacity:1,transform:leftTransform}
  ],620,"cubic-bezier(.12,.9,.18,1)").finished;

  /* Shockwave + both follow-through moves at once. */
  shockwave.style.left=(mr.left-gap/2)+"px";
  shockwave.style.top=(mr.top+mr.height*.5)+"px";
  animate(shockwave,[
    {opacity:0,transform:"translate(-50%,-50%) scale(.2)"},
    {opacity:.95,transform:"translate(-50%,-50%) scale(.7)"},
    {opacity:0,transform:"translate(-50%,-50%) scale(1.8)"}
  ],260,"cubic-bezier(.16,.8,.2,1)");

  const antiFollow=animate(anti,[
    {opacity:1,transform:leftTransform},
    {opacity:1,transform:"translate(calc(-50% - 3vw),-50%)",offset:.45},
    {opacity:1,transform:finalAnti}
  ],520,"cubic-bezier(.12,.88,.16,1)");
  const mainBoost=animate(main,[
    {opacity:1,transform:"translate(-50%,-50%)"},
    {opacity:1,transform:"translate(calc(-50% - 10vw),-50%)",offset:.08},
    {opacity:1,transform:"translate(calc(-50% - 72vw),-50%)",offset:.38},
    {opacity:1,transform:"translate(-170vw,-50%)"}
  ],520,"cubic-bezier(.04,.92,.1,1)");
  await Promise.all([antiFollow.finished,mainBoost.finished]);

  /* SECURLY returns from the right underneath ANTI. */
  await animate(main,[
    {opacity:1,transform:"translate(165vw,"+off+"px)"},
    {opacity:1,transform:"translate(95vw,"+off+"px)",offset:.18},
    {opacity:1,transform:"translate(-20vw,"+off+"px)",offset:.72},
    {opacity:1,transform:"translate(-50%,"+off+"px)"}
  ],780,"cubic-bezier(.16,.82,.18,1)").finished;

  /* Strike line drops into place as the final underline. */
  line.style.opacity="1";
  await wait(120);
  line.style.transition="top .42s cubic-bezier(.2,.8,.2,1)";
  line.style.top="calc(100% + 4px)";
  await wait(520+650);

  /* Wait (max 8s) for novene itself to finish loading behind the screen. */
  await Promise.race([ready,wait(8000)]);

  /* Boot screen out, novene pops in. */
  b.style.transition="opacity .25s ease, visibility .25s ease";
  b.style.opacity="0";
  b.style.visibility="hidden";
  if(f){
    f.style.transition="opacity .35s ease, transform .35s cubic-bezier(.2,1.2,.3,1)";
    f.style.opacity="1";
    f.style.transform="scale(1)";
  }
  await wait(300);
  b.remove();
}

window.addEventListener("load",function(){playBoot();});
})();
